<template>
  <div class="space-y-5">
    <div class="breadcrumbs text-sm"><ul><li><NuxtLink to="/spoc-submissions">SPOC submissions</NuxtLink></li><li>{{ item?.reference_number || 'Case' }}</li></ul></div>
    <div v-if="loading" class="flex justify-center py-20"><span class="loading loading-spinner loading-lg" /></div>
    <template v-else-if="item">
      <header class="rounded-2xl border border-base-200 bg-base-100 p-5 shadow-sm">
        <div class="flex flex-wrap justify-between gap-4"><div><div class="flex flex-wrap items-center gap-2"><span class="badge badge-primary">{{ label(item.status) }}</span><span class="badge badge-outline">{{ item.submission_type }}</span><span class="font-mono text-xs">{{ item.reference_number }}</span></div><h1 class="mt-3 text-2xl font-bold">{{ item.tender?.title }}</h1><p class="text-sm text-base-content/60">{{ item.tender?.tendernumber }} · {{ item.tender?.company?.name }}</p></div><NuxtLink v-if="agenda" :to="`/spoc-agendas/${agenda.uuid}`" class="btn btn-outline btn-sm"><Icon name="lucide:calendar-range" />{{ agenda.agenda_number }}</NuxtLink></div>
      </header>

      <div class="grid gap-5 xl:grid-cols-[1fr_380px]">
        <main class="space-y-5">
          <section class="rounded-2xl border border-base-200 bg-base-100 p-5"><h2 class="font-bold">Procurement submission</h2><div class="mt-4 grid gap-4 sm:grid-cols-2 lg:grid-cols-3"><SpocInfo label="Proposed PE action" :value="label(item.proposed_action)" /><SpocInfo label="Procurement method" :value="item.tender?.procurementmethod?.name" /><SpocInfo label="Procurement group" :value="item.tender?.procurementgroup?.name" /><SpocInfo label="Submitted" :value="date(item.submitted_at)" /><SpocInfo label="Current assignee" :value="person(item.current_assignee)" /><SpocInfo label="Parent case" :value="item.parent_submission?.reference_number || 'New submission'" /></div></section>

          <section class="rounded-2xl border border-base-200 bg-base-100 p-5">
            <div class="flex flex-wrap items-start justify-between gap-3">
              <div><h2 class="font-bold">Tender dossier from the approved SBD</h2><p class="mt-1 text-sm text-base-content/55">Source data is populated directly from the tender and remains read-only for the SPOC assessment.</p></div>
              <a v-if="item.tender?.sbd?.download_url" :href="item.tender.sbd.download_url" target="_blank" rel="noopener" class="btn btn-outline btn-sm"><Icon name="lucide:file-text" />View full SBD</a>
            </div>
            <div class="mt-4 grid gap-3 sm:grid-cols-2 lg:grid-cols-4">
              <SpocInfo label="Tender number" :value="item.tender?.tendernumber" />
              <SpocInfo label="Proposal envelopes" :value="item.tender?.proposal_mode === 'TWO' ? 'Two-envelope' : label(item.tender?.proposal_mode)" />
              <SpocInfo label="Evaluation method" :value="item.tender?.evaluation_scheme?.method?.name || item.tender?.bidevaluationmethod?.name" />
              <SpocInfo label="Technical threshold" :value="item.tender?.evaluation_scheme?.technical_threshold ? `${formatNumber(item.tender.evaluation_scheme.technical_threshold)}%` : 'Not specified'" />
              <SpocInfo label="Closing" :value="date(item.tender?.closing_at)" />
              <SpocInfo label="Opening" :value="date(item.tender?.opening_at)" />
              <SpocInfo label="Bid validity" :value="item.tender?.bid_validity_period ? `${item.tender.bid_validity_period} days` : 'Not specified'" />
              <SpocInfo label="Bid security" :value="item.tender?.sbd?.field_values?.bid_security_value || 'Not specified'" />
            </div>
            <div v-if="sbdEntries.length" class="mt-5 overflow-x-auto"><h3 class="mb-2 text-sm font-bold">SBD populated particulars</h3><table class="table table-sm"><thead><tr><th class="w-64">SBD field</th><th>Approved value</th></tr></thead><tbody><tr v-for="entry in sbdEntries" :key="entry.key"><td class="align-top font-medium">{{ label(entry.key) }}</td><td class="whitespace-pre-wrap">{{ displayValue(entry.value) }}</td></tr></tbody></table></div>
          </section>

          <section class="rounded-2xl border border-base-200 bg-base-100 p-5">
            <div class="flex flex-wrap items-center justify-between gap-2"><div><h2 class="font-bold">Document eligibility</h2><p class="text-sm text-base-content/55">Documents bidders were required to submit.</p></div><span class="badge badge-outline">{{ documentRequirements.length }} requirements</span></div>
            <div class="mt-4 overflow-x-auto"><table class="table table-sm"><thead><tr><th>#</th><th>Required document</th><th>Description</th><th>Expiry controlled</th><th>Historical</th></tr></thead><tbody><tr v-for="(row, index) in documentRequirements" :key="row.id"><td>{{ index + 1 }}</td><td class="font-medium">{{ row.tender_document?.name }}</td><td>{{ row.tender_document?.description || '—' }}</td><td>{{ yesNo(row.tender_document?.expires) }}</td><td>{{ yesNo(row.tender_document?.historical) }}</td></tr><tr v-if="!documentRequirements.length"><td colspan="5" class="text-center text-base-content/45">No document eligibility requirements were configured.</td></tr></tbody></table></div>
          </section>

          <section class="rounded-2xl border border-base-200 bg-base-100 p-5">
            <div class="flex flex-wrap items-center justify-between gap-2"><div><h2 class="font-bold">Mandatory eligibility criteria</h2><p class="text-sm text-base-content/55">Pass/fail questions configured in the tender.</p></div><span class="badge badge-outline">{{ eligibilityQuestions.length }} criteria</span></div>
            <div class="mt-4 space-y-4"><div v-for="group in eligibilityGroups" :key="group.title" class="overflow-hidden rounded-xl border border-base-200"><div class="bg-base-200/50 px-4 py-2 font-semibold">{{ group.title }}</div><table class="table table-sm"><thead><tr><th class="w-12">#</th><th>Criterion</th><th class="w-32">Response type</th></tr></thead><tbody><tr v-for="(row, index) in group.questions" :key="row.uuid"><td>{{ index + 1 }}</td><td>{{ row.question }}</td><td><span class="badge badge-ghost badge-sm">{{ label(row.response_type) }}</span></td></tr></tbody></table></div><p v-if="!eligibilityGroups.length" class="text-sm text-base-content/45">No mandatory eligibility criteria were configured.</p></div>
          </section>

          <section class="rounded-2xl border border-base-200 bg-base-100 p-5">
            <div class="flex flex-wrap items-center justify-between gap-2"><div><h2 class="font-bold">Technical evaluation criteria</h2><p class="text-sm text-base-content/55">Group and question weights are reproduced from the approved tender.</p></div><span class="badge badge-outline">{{ technicalQuestions.length }} questions</span></div>
            <div class="mt-4 space-y-4"><div v-for="group in technicalGroups" :key="group.key" class="overflow-hidden rounded-xl border border-base-200"><div class="flex flex-wrap items-center justify-between gap-2 bg-base-200/50 px-4 py-3"><div><p class="font-semibold">{{ group.title }}</p><p v-if="group.scope" class="text-xs text-base-content/50">{{ group.scope }}</p></div><span class="badge badge-info badge-outline">Group weight {{ formatNumber(group.weight) }}</span></div><div class="overflow-x-auto"><table class="table table-sm"><thead><tr><th class="w-12">#</th><th>Technical question</th><th class="w-28">Type</th><th class="w-32">Question weight</th></tr></thead><tbody><tr v-for="(row, index) in group.questions" :key="row.uuid"><td>{{ index + 1 }}</td><td>{{ row.question }}</td><td><span class="badge badge-ghost badge-sm">{{ label(row.response_type) }}</span></td><td>{{ formatNumber(row.question_weight) }}%</td></tr></tbody></table></div></div><p v-if="!technicalGroups.length" class="text-sm text-base-content/45">No technical criteria were configured.</p></div>
          </section>

          <section class="rounded-2xl border border-base-200 bg-base-100 p-5">
            <div class="flex flex-wrap items-center justify-between gap-2"><div><h2 class="font-bold">Evaluation outcome submitted to SPOC</h2><p class="text-sm text-base-content/55">Technical, financial and total results from the final evaluation report.</p></div><span class="badge badge-outline">{{ evaluationRows.length }} bidder{{ evaluationRows.length === 1 ? '' : 's' }}</span></div>
            <div class="mt-4 overflow-x-auto"><table class="table table-sm"><thead><tr><th>Rank</th><th>Bidder</th><th>Technical</th><th>Financial</th><th>Total</th><th>Evaluated quotation</th><th>Outcome</th></tr></thead><tbody><tr v-for="row in evaluationRows" :key="row.supplier_bid_id"><td>{{ row.rank || '—' }}</td><td class="font-medium">{{ bidderName(row.supplier_bid_id) }}</td><td>{{ formatNumber(row.consensus_technical_score) }}</td><td>{{ formatNumber(row.consensus_financial_score) }}</td><td class="font-semibold">{{ formatNumber(row.consensus_total_score) }}</td><td>{{ money(row.evaluated_amount) }}</td><td><span :class="['badge badge-sm', row.recommended ? 'badge-success' : row.passed ? 'badge-info badge-outline' : 'badge-error badge-outline']">{{ row.recommended ? 'Recommended' : row.passed ? 'Passed' : 'Not compliant' }}</span></td></tr><tr v-if="!evaluationRows.length"><td colspan="7" class="text-center text-base-content/45">No final evaluation result snapshot is available.</td></tr></tbody></table></div>
          </section>

          <section v-if="item.specialist_observations" class="rounded-2xl border border-base-200 bg-base-100 p-5"><h2 class="font-bold">Internal review trail</h2><div class="mt-4 grid gap-4 lg:grid-cols-3"><SpocReview title="Procurement Specialist" :decision="item.specialist_recommendation" :directive="item.specialist_directive" :comments="item.specialist_observations" /><SpocReview title="Assigning Manager" :decision="item.manager_recommendation || item.manager_decision" :directive="item.manager_directive" :comments="item.manager_comments" /><SpocReview title="Presenting Director" :decision="item.director_recommendation || item.director_decision" :directive="item.director_directive" :comments="item.director_comments" /></div></section>

          <section v-if="assessmentEntries.length" class="rounded-2xl border border-base-200 bg-base-100 p-5"><div class="flex flex-wrap items-center justify-between gap-2"><div><h2 class="font-bold">Completed evaluation template</h2><p class="text-sm text-base-content/55">{{ templateTitle }}</p></div><span class="badge badge-outline">{{ assessmentEntries.length }} sections</span></div><div class="mt-4 overflow-x-auto"><table class="table table-sm"><thead><tr><th class="w-56">Template section</th><th>Specialist assessment</th></tr></thead><tbody><tr v-for="entry in assessmentEntries" :key="entry.key"><td class="align-top font-medium">{{ entry.label }}</td><td class="whitespace-pre-line text-base-content/75">{{ entry.value }}</td></tr></tbody></table></div></section>

          <section v-if="item.case" class="rounded-2xl border border-base-200 bg-base-100 p-5"><div class="flex justify-between"><div><h2 class="font-bold">SPOC committee</h2><p class="text-sm text-base-content/55">The four statutory voting roles are assigned. A minimum of three conflict-free substantive decisions forms the Round Robin quorum.</p></div><span class="badge badge-outline">Quorum {{ item.case.quorum_required }}</span></div><div class="mt-4 overflow-x-auto"><table class="table table-sm"><thead><tr><th>Member</th><th>Statutory role</th><th>Conflict</th><th>Decision state</th></tr></thead><tbody><tr v-for="member in item.case.members" :key="member.id"><td>{{ person(member.user) }}</td><td>{{ label(member.statutory_role) }}</td><td><span class="badge badge-sm" :class="member.conflict_status === 'CLEAR' ? 'badge-success' : 'badge-warning'">{{ label(member.conflict_status) }}</span></td><td>{{ member.vote || member.vote_submitted ? 'Submitted' : 'Pending' }}</td></tr><tr v-if="!item.case.members?.length"><td colspan="4" class="text-center text-base-content/45">Committee members have not been assigned.</td></tr></tbody></table></div><form v-if="can('can.edit.spoccases') && !item.case.members?.length" class="mt-4 grid gap-3 md:grid-cols-2" @submit.prevent="submitMembers"><label v-for="role in statutoryRoles" :key="role" class="form-control"><span class="label-text mb-1">{{ label(role) }}</span><select v-model="memberAssignments[role]" class="select select-bordered" required><option value="">Select member</option><option v-for="user in users" :key="user.id" :value="user.id">{{ person(user) }}</option></select></label><button class="btn btn-primary md:col-span-2" :disabled="saving">Assign statutory committee</button></form><div v-if="myMembership && myMembership.conflict_status === 'PENDING'" class="mt-4 flex flex-wrap gap-2"><button class="btn btn-success btn-sm" @click="declareConflict('CLEAR')">Declare no conflict</button><button class="btn btn-warning btn-sm" @click="declareConflict('CONFLICT')">Declare conflict</button></div></section>

          <section v-if="latestRecord" class="rounded-2xl border border-base-200 bg-base-100 p-5"><h2 class="font-bold">Committee record confirmation</h2><p class="mt-1 text-sm text-base-content/60">Version {{ latestRecord.version }} · {{ latestRecord.filename }}</p><div class="mt-4 grid gap-3 sm:grid-cols-2"><div v-for="confirmation in latestRecord.confirmations" :key="confirmation.id" class="rounded-xl border border-base-200 p-3"><div class="flex justify-between gap-2"><span class="font-medium">{{ person(confirmation.user) }}</span><span class="badge badge-sm">{{ label(confirmation.status) }}</span></div><p v-if="confirmation.comments" class="mt-2 text-xs text-base-content/60">{{ confirmation.comments }}</p></div></div></section>
        </main>

        <aside class="space-y-5">
          <section class="rounded-2xl border border-primary/20 bg-base-100 p-5 shadow-sm"><div class="flex flex-wrap items-center justify-between gap-2"><h2 class="font-bold">Current action</h2><label :class="['flex items-center gap-1.5 rounded-full px-2.5 py-1 text-xs font-semibold', priorityStyle(item.priority)]"><span class="h-2 w-2 rounded-full bg-current" /><select v-model="item.priority" class="cursor-pointer appearance-none bg-transparent pr-1 outline-none" :disabled="saving || !can('can.edit.spoccases')" aria-label="SPOC case priority" @change="savePriority"><option value="HIGH">High Priority</option><option value="URGENT">Urgent</option><option value="EXTREME">Extreme Priority</option></select><Icon name="lucide:chevron-down" class="h-3 w-3" /></label></div><p class="mt-1 text-sm text-base-content/60">{{ actionHelp }}</p>
            <form v-if="item.status === 'SUBMITTED'" class="mt-4 space-y-3" @submit.prevent="submitAssign"><select v-model="form.officer_id" class="select w-full" required><option value="">Procurement Specialist</option><option v-for="user in users" :key="user.id" :value="user.id">{{ personOption(user) }}</option></select><textarea v-model="form.comments" class="textarea w-full" placeholder="Assignment note" /><button class="btn btn-primary w-full" :disabled="saving">Assign submission</button></form>
            <form v-else-if="item.status === 'ASSIGNED_FOR_CASE_CREATION'" class="mt-4 space-y-4" @submit.prevent="submitSpecialist"><div class="rounded-xl border border-primary/25 bg-primary/5 p-3"><p class="text-xs font-semibold uppercase tracking-wide text-primary">Relevant case template</p><p class="mt-1 font-bold">{{ templateTitle }}</p><p class="mt-1 text-xs text-base-content/55">Complete every section before sending the case to the assigning manager.</p></div><div v-if="item.submission_type === 'RESUBMISSION' && item.parent_submission?.case" class="rounded-xl border border-warning/30 bg-warning/5 p-3 text-sm"><p class="font-semibold">Previous SPOC resolution</p><p class="mt-1">{{ item.parent_submission.case.decision }} · {{ label(item.parent_submission.case.provisional_directive) }}</p><p class="mt-1 text-xs text-base-content/60">{{ item.parent_submission.case.decision_reasons }}</p></div><label v-for="field in templateFields" :key="field.key" class="form-control"><span class="label-text mb-1 font-medium">{{ field.label }} *</span><textarea v-model.trim="form.assessment[field.key]" class="textarea textarea-bordered min-h-24 w-full" :placeholder="field.placeholder" required /></label><label class="form-control"><span class="label-text mb-1 font-medium">Overall observations *</span><textarea v-model="form.observations" class="textarea textarea-bordered h-32 w-full" placeholder="Summarise the material findings and compliance concerns." required /></label><select v-model="form.recommendation" class="select w-full" required><option value="CERTIFY">Recommend CERTIFY</option><option value="NOT_CERTIFY">Recommend NOT CERTIFY</option></select><select v-model="form.directive" class="select w-full" required><option v-for="value in directives" :key="value" :value="value">{{ label(value) }}</option></select><textarea v-model.trim="form.comments" class="textarea textarea-bordered w-full" placeholder="Recommendation rationale" /><select v-model="form.manager_id" class="select w-full" required><option value="">Assigning Manager</option><option v-for="user in users" :key="user.id" :value="user.id">{{ person(user) }}</option></select><button class="btn btn-primary w-full" :disabled="saving"><Icon name="lucide:send" />Send completed template to manager</button></form>
            <form v-else-if="['MANAGER_REVIEW','AWAITING_APPROVAL'].includes(item.status)" class="mt-4 space-y-3" @submit.prevent="submitStaff"><select v-model="form.action" class="select w-full" required><option value="ENDORSE">Endorse</option><option value="AMEND_AND_ENDORSE">Amend and endorse</option><option value="RETURN">Return with reasons</option></select><textarea v-model="form.comments" class="textarea h-28 w-full" placeholder="Review comments and reasons" required /><template v-if="form.action !== 'RETURN'"><select v-model="form.recommendation" class="select w-full"><option value="CERTIFY">CERTIFY</option><option value="NOT_CERTIFY">NOT CERTIFY</option></select><select v-model="form.directive" class="select w-full"><option v-for="value in directives" :key="value" :value="value">{{ label(value) }}</option></select><select v-if="item.status === 'MANAGER_REVIEW'" v-model="form.approver_id" class="select w-full" required><option value="">Presenting Director</option><option v-for="user in users" :key="user.id" :value="user.id">{{ person(user) }}</option></select></template><button class="btn btn-primary w-full" :disabled="saving">{{ form.action === 'RETURN' ? 'Return case' : 'Submit review' }}</button></form>
            <form v-else-if="item.status === 'UNDER_REVIEW' && item.case?.deliberation_mode === 'ROUND_ROBIN'" class="mt-4 space-y-3" @submit.prevent="submitVote"><select v-model="form.decision" class="select w-full"><option value="CERTIFY">CERTIFY</option><option value="NOT_CERTIFY">NOT CERTIFY</option><option value="ABSTAIN">ABSTAIN</option></select><select v-if="form.decision !== 'ABSTAIN'" v-model="form.directive" class="select w-full"><option v-for="value in directives" :key="value" :value="value">{{ label(value) }}</option></select><textarea v-model="form.reasons" class="textarea h-28 w-full" placeholder="Decision reasons" required /><button class="btn btn-primary w-full" :disabled="saving">Submit private decision</button><button v-if="can('can.decide.spoccases')" type="button" class="btn btn-outline w-full" :disabled="saving" @click="closeRoundRobin">Close Round Robin and calculate decision</button></form>
            <form v-else-if="item.status === 'UNDER_REVIEW'" class="mt-4 space-y-3" @submit.prevent="submitSitting"><select v-model="form.decision" class="select w-full"><option value="CERTIFY">CERTIFY</option><option value="NOT_CERTIFY">NOT CERTIFY</option></select><select v-model="form.directive" class="select w-full"><option v-for="value in directives" :key="value" :value="value">{{ label(value) }}</option></select><fieldset class="rounded-xl border border-base-200 p-3"><legend class="px-1 text-xs font-bold">Members in attendance</legend><label v-for="member in item.case?.members" :key="member.id" class="mt-2 flex items-center gap-2 text-sm"><input v-model="form.attendee_user_ids" type="checkbox" :value="member.user_id" class="checkbox checkbox-sm" />{{ person(member.user) }} · {{ label(member.statutory_role) }}</label></fieldset><textarea v-model="form.reasons" class="textarea h-28 w-full" placeholder="Committee reasons" required /><button class="btn btn-primary w-full" :disabled="saving">Record provisional decision</button></form>
            <form v-else-if="item.status === 'AWAITING_RECORD_CONFIRMATION' && (!latestRecord || (recordNeedsChanges && can('can.manage.spocagendas')))" class="mt-4 space-y-3" @submit.prevent="submitRecord"><label class="form-control"><span class="label-text mb-1">{{ latestRecord ? 'Revised committee record' : 'Committee minutes / decision record' }}</span><input type="file" accept=".pdf,.doc,.docx" class="file-input file-input-bordered w-full" required @change="form.record = $event.target.files?.[0]" /></label><p class="text-xs text-base-content/55">This version will be circulated to every conflict-free voting member for confirmation.</p><button class="btn btn-primary w-full" :disabled="saving || !form.record">Circulate {{ latestRecord ? 'new version' : 'record' }}</button></form>
            <div v-else-if="item.status === 'AWAITING_RECORD_CONFIRMATION' && recordNeedsChanges" class="alert alert-warning mt-4 text-sm"><Icon name="lucide:file-warning" />Changes were requested. The Secretariat must circulate a revised record.</div>
            <form v-else-if="item.status === 'AWAITING_RECORD_CONFIRMATION' && latestRecord" class="mt-4 space-y-3" @submit.prevent="submitConfirmation"><select v-model="form.confirmation_status" class="select w-full"><option value="CONFIRMED">Confirm record</option><option value="CHANGES_REQUESTED">Request changes</option></select><textarea v-model="form.comments" class="textarea w-full" placeholder="Comments" /><button class="btn btn-primary w-full" :disabled="saving">Save response</button></form>
            <form v-else-if="item.status === 'AWAITING_RESOLUTION'" class="mt-4 space-y-3" @submit.prevent="submitFinalize"><textarea v-model="form.comments" class="textarea h-28 w-full" placeholder="Final resolution comments" required /><button class="btn btn-primary w-full" :disabled="saving">Issue final resolution</button></form>
            <div v-else class="alert mt-4 text-sm"><Icon name="lucide:info" /><span>{{ actionHelp }}</span></div>
          </section>
          <section class="rounded-2xl border border-base-200 bg-base-100 p-5"><h2 class="font-bold">Audit trail</h2><ol class="mt-4 space-y-4"><li v-for="event in [...(item.events || [])].reverse()" :key="event.id" class="border-l-2 border-base-300 pl-3"><p class="text-sm font-medium">{{ label(event.action) }}</p><p class="text-xs text-base-content/55">{{ person(event.user) }} · {{ date(event.occurred_at) }}</p><p v-if="event.comments" class="mt-1 text-xs">{{ event.comments }}</p></li></ol></section>
        </aside>
      </div>
    </template>
  </div>
</template>

<script setup>
definePageMeta({ layout: 'default' });
const route = useRoute(); const api = useSpocWorkflowHelper(); const usersApi = useUserHelper(); const toast = useToast(); const identity = useSanctumUser(); const { can } = useCheckPermission();
const item = ref(null); const users = ref([]); const loading = ref(true); const saving = ref(false);
const form = reactive({ officer_id: '', manager_id: '', approver_id: '', action: 'ENDORSE', observations: '', comments: '', recommendation: 'CERTIFY', decision: 'CERTIFY', directive: 'AWARD', reasons: '', confirmation_status: 'CONFIRMED', record: null, attendee_user_ids: [], assessment: {} });
const statutoryRoles = ['ATTORNEY_GENERAL', 'AUDITOR_GENERAL', 'ACCOUNTANT_GENERAL', 'PRINCIPAL_DIRECTOR_PUBLIC_WORKS'];
const memberAssignments = reactive(Object.fromEntries(statutoryRoles.map(role => [role, ''])));
const directives = computed(() => (form.recommendation === 'NOT_CERTIFY' || form.decision === 'NOT_CERTIFY') ? ['CANCEL_TENDER', 'RESUBMISSION_REQUIRED'] : ['AWARD', 'CANCEL_TENDER']);
const newSubmissionFields = [
  { key: 'pmu_review', label: 'PMU review', placeholder: 'Review the procurement-management-unit submission and identify material observations.' },
  { key: 'sbd_review', label: 'Standard bidding document review', placeholder: 'Assess the approved solicitation document and material compliance requirements.' },
  { key: 'advert_review', label: 'Advertisement and solicitation review', placeholder: 'Confirm publication, solicitation period and applicable procurement method.' },
  { key: 'bidder_list_review', label: 'Bidder and submission review', placeholder: 'Record participating bidders and any material submission issues.' },
  { key: 'qualification_review', label: 'Qualification and eligibility review', placeholder: 'Assess mandatory eligibility and qualification findings.' },
  { key: 'technical_review', label: 'Technical evaluation review', placeholder: 'Review technical scoring, responsiveness and evaluator consistency.' },
  { key: 'comparative_schedule_review', label: 'Comparative schedule and financial review', placeholder: 'Review evaluated prices, arithmetic checks, ranking and value-for-money considerations.' },
  { key: 'evaluation_committee_review', label: 'Evaluation committee and award recommendation', placeholder: 'Assess committee composition, declarations, minutes and the proposed outcome.' },
  { key: 'violations', label: 'Observed violations or exceptions', placeholder: 'Record any legal, procedural or documentary violation. State none where applicable.' },
  { key: 'remedies', label: 'Proposed remedies', placeholder: 'Record corrective action or safeguards recommended before the case proceeds.' },
];
const resubmissionFields = [
  { key: 'original_case_background', label: 'Original case background', placeholder: 'Summarise the original submission and review history.' },
  { key: 'original_spoc_resolution', label: 'Original SPOC resolution', placeholder: 'Record the prior decision, directive and required corrective action.' },
  { key: 'issues_to_action', label: 'Issues and comments to action', placeholder: 'List every issue the procurement entity was required to address.' },
  { key: 'reassessment', label: 'Resubmission reassessment', placeholder: 'Evaluate the revised submission against the original concerns.' },
  { key: 'issues_addressed', label: 'Evidence that issues were addressed', placeholder: 'Describe the corrective evidence supplied for each issue.' },
  { key: 'outstanding_issues', label: 'Outstanding issues or new concerns', placeholder: 'Record unresolved matters or new compliance concerns. State none where applicable.' },
];
const templateTitle = computed(() => item.value?.submission_type === 'RESUBMISSION' ? 'Resubmission Evaluation Template' : 'New Submission Evaluation Template');
const templateFields = computed(() => item.value?.submission_type === 'RESUBMISSION' ? resubmissionFields : newSubmissionFields);
const assessmentEntries = computed(() => templateFields.value.map(field => ({ ...field, value: item.value?.specialist_assessment?.[field.key] })).filter(entry => entry.value));
const documentRequirements = computed(() => item.value?.tender?.tender_document_requirements ?? []);
const eligibilityQuestions = computed(() => item.value?.tender?.eligibility_questions ?? []);
const technicalQuestions = computed(() => item.value?.tender?.technical_eligibility_questions ?? []);
const groupRows = (rows, fallback) => [...rows].sort((a, b) => Number(a.group_sort_order ?? 0) - Number(b.group_sort_order ?? 0) || Number(a.sort_order ?? 0) - Number(b.sort_order ?? 0)).reduce((groups, row) => { const title = row.group_title || fallback; let group = groups.find(entry => entry.title === title); if (!group) { group = { title, questions: [] }; groups.push(group); } group.questions.push(row); return groups; }, []);
const eligibilityGroups = computed(() => groupRows(eligibilityQuestions.value, 'General eligibility'));
const technicalGroups = computed(() => groupRows(technicalQuestions.value, 'General technical criteria').map((group, index) => ({ ...group, key: `${index}-${group.title}`, weight: group.questions[0]?.group_weight ?? 0, scope: group.questions[0]?.product?.description || group.questions[0]?.lot?.description || null })));
const sbdEntries = computed(() => Object.entries(item.value?.tender?.sbd?.field_values ?? {}).filter(([, value]) => value !== null && value !== '').map(([key, value]) => ({ key, value })));
const evaluationRows = computed(() => {
  const snapshot = item.value?.submission_snapshot?.evaluation_results;
  if (Array.isArray(snapshot) && snapshot.length) return snapshot.map(row => ({ ...row, consensus_technical_score: row.technical_score, consensus_financial_score: row.financial_score, consensus_total_score: row.total_score, passed: Number(row.technical_score) > 0 }));
  return [...(item.value?.evaluation_report?.report_snapshot ?? [])].sort((a, b) => Number(a.rank ?? 999) - Number(b.rank ?? 999));
});
const agenda = computed(() => item.value?.case?.agenda_items?.at(-1)?.agenda);
const latestRecord = computed(() => item.value?.case?.record_versions?.at(-1));
const recordNeedsChanges = computed(() => latestRecord.value?.confirmations?.some(row => row.status === 'CHANGES_REQUESTED'));
const myMembership = computed(() => item.value?.case?.members?.find(member => Number(member.user_id) === Number(identity.value?.id)));
const priorityStyle = priority => ({ HIGH: 'bg-info/15 text-info', URGENT: 'bg-warning/20 text-warning', EXTREME: 'bg-error/15 text-error' }[priority] || 'bg-info/15 text-info');
const person = user => user ? [user.name, user.lastname].filter(Boolean).join(' ') || user.email : '—';
const personOption = user => user ? `${person(user)} · ${user.email || 'No email'}${Number(user.id) === Number(identity.value?.id) ? ' (You)' : ''}` : '—';
const label = value => String(value || '—').replaceAll('_', ' ').toLowerCase().replace(/\b\w/g, c => c.toUpperCase());
const date = value => value ? new Date(value).toLocaleString('en-ZW', { dateStyle: 'medium', timeStyle: 'short' }) : '—';
const formatNumber = value => value === null || value === undefined || value === '' ? '—' : new Intl.NumberFormat('en-ZW', { maximumFractionDigits: 2 }).format(Number(value));
const displayValue = value => typeof value === 'boolean' ? (value ? 'Yes' : 'No') : Array.isArray(value) ? value.join(', ') : String(value ?? '—');
const yesNo = value => ['Y', 'YES', '1', 1, true].includes(value) ? 'Yes' : 'No';
const bidderName = bidId => evaluationRows.value.find(row => Number(row.supplier_bid_id) === Number(bidId))?.bidder?.name || item.value?.tender?.supplier_bids?.find(bid => Number(bid.id) === Number(bidId))?.company?.name || `Bid ${bidId}`;
const money = value => value === null || value === undefined ? '—' : `${item.value?.submission_snapshot?.currency?.code || ''} ${formatNumber(value)}`.trim();
const prefillAssessment = () => {
  if (!item.value || item.value.specialist_assessment || item.value.status !== 'ASSIGNED_FOR_CASE_CREATION') return;
  const groups = technicalGroups.value.map(group => `${group.title} (${formatNumber(group.weight)})`).join(', ');
  const ranked = evaluationRows.value.map(row => `${row.rank || '—'}. ${row.bidder?.name || bidderName(row.supplier_bid_id)} — technical ${formatNumber(row.consensus_technical_score)}, financial ${formatNumber(row.consensus_financial_score)}, total ${formatNumber(row.consensus_total_score)}, quotation ${money(row.evaluated_amount)}`).join('\n');
  Object.assign(form.assessment, {
    sbd_review: `Generated SBD ${item.value.tender?.sbd?.generated_filename || 'record'} reviewed. ${sbdEntries.value.length} populated SBD particulars are available in the tender dossier above.`,
    bidder_list_review: `${item.value.tender?.supplier_bids?.length || evaluationRows.value.length} bidder submission(s) are recorded in the tender.\n${ranked}`,
    qualification_review: `${documentRequirements.value.length} document eligibility requirement(s) and ${eligibilityQuestions.value.length} mandatory eligibility criterion/criteria are configured in the approved tender.`,
    technical_review: `${technicalQuestions.value.length} technical question(s) across ${technicalGroups.value.length} weighted group(s). ${groups || 'No technical groups configured.'} Technical threshold: ${formatNumber(item.value.tender?.evaluation_scheme?.technical_threshold)}%.`,
    comparative_schedule_review: ranked || 'No final evaluated bidder ranking is available.',
    evaluation_committee_review: `Final evaluation report status: ${label(item.value.evaluation_report?.status)}. Recommendation: ${item.value.evaluation_report?.recommendation || 'Not recorded.'}`,
  });
};
const actionHelp = computed(() => ({ SUBMITTED: 'Assign the new submission to a Procurement Specialist.', ASSIGNED_FOR_CASE_CREATION: 'Prepare observations and a recommendation, then send the case to the assigning manager.', MANAGER_REVIEW: 'Review the specialist assessment. Amendments require recorded reasons.', AWAITING_APPROVAL: 'The presenting Director endorses or returns the internal recommendation.', AWAITING_AGENDA: 'This case is ready to be placed on a Round Robin or Sitting agenda.', UNDER_REVIEW: 'The committee is deliberating on this case.', AWAITING_RECORD_CONFIRMATION: 'All conflict-free attending members must confirm the current record version.', AWAITING_RESOLUTION: 'The confirmed committee decision can now be issued as the final resolution.', COMPLETED: 'The SPOC resolution is complete.' }[item.value?.status] || 'No action is available.'));
const load = async () => { loading.value = true; const [{ data, error }, userResult] = await Promise.all([api.show(route.params.uuid), usersApi.getUsers('', 1, 100)]); loading.value = false; if (error) return toast.error({ title: 'Could not load case', message: error?.data?.message }); item.value = data?.data; item.value.priority ||= 'HIGH'; users.value = userResult.data?.data?.data ?? userResult.data?.data ?? []; prefillAssessment(); useHead({ title: item.value?.reference_number || 'SPOC case' }); };
const run = async action => { saving.value = true; const { data, error } = await action(); saving.value = false; if (error || data?.status === false) return toast.error({ title: 'Action failed', message: error?.data?.message || data?.message }); item.value = data.data; toast.success({ title: 'SPOC workflow updated' }); };
const runReload = async action => { saving.value = true; const { data, error } = await action(); saving.value = false; if (error || data?.status === false) return toast.error({ title: 'Action failed', message: error?.data?.message || data?.message }); await load(); toast.success({ title: 'SPOC workflow updated' }); };
const submitAssign = () => run(() => api.assign(item.value.uuid, { officer_id: Number(form.officer_id), comments: form.comments || null }));
const savePriority = () => run(() => api.priority(item.value.uuid, item.value.priority));
const submitSpecialist = () => run(() => api.specialistReview(item.value.uuid, { manager_id: Number(form.manager_id), observations: form.observations, recommendation: form.recommendation, directive: form.directive, comments: form.comments || null, assessment: { ...form.assessment, template: item.value.submission_type, template_name: templateTitle.value, completed_at: new Date().toISOString() } }));
const submitStaff = () => run(() => (item.value.status === 'MANAGER_REVIEW' ? api.managerReview : api.directorReview)(item.value.uuid, { action: form.action, comments: form.comments, recommendation: form.action === 'RETURN' ? null : form.recommendation, directive: form.action === 'RETURN' ? null : form.directive, approver_id: form.action !== 'RETURN' && item.value.status === 'MANAGER_REVIEW' ? Number(form.approver_id) : null }));
const submitVote = () => runReload(() => api.vote(item.value.case.uuid, { decision: form.decision, directive: form.decision === 'ABSTAIN' ? null : form.directive, reasons: form.reasons, comments: form.comments || null }));
const closeRoundRobin = () => { const comments = window.prompt('Record the reason for closing this Round Robin:'); if (comments) return run(() => api.closeRoundRobin(item.value.uuid, comments)); };
const submitSitting = () => run(() => api.sittingDecision(item.value.uuid, { decision: form.decision, directive: form.directive, reasons: form.reasons, corrective_actions: [], meeting_details: { attendee_user_ids: form.attendee_user_ids.map(Number) } }));
const submitRecord = () => { const body = new FormData(); body.append('record', form.record); return run(() => api.circulateRecord(item.value.uuid, body)); };
const submitMembers = () => runReload(() => api.assignMembers(item.value.case.uuid, statutoryRoles.map(role => ({ statutory_role: role, user_id: Number(memberAssignments[role]) }))));
const declareConflict = status => { const details = status === 'CONFLICT' ? window.prompt('Describe the conflict of interest:') : null; if (status === 'CONFLICT' && !details) return; return runReload(() => api.declareConflict(item.value.case.uuid, { status, details })); };
const submitConfirmation = () => run(() => api.confirmRecord(item.value.uuid, { status: form.confirmation_status, comments: form.comments || null }));
const submitFinalize = () => run(() => api.finalize(item.value.uuid, form.comments));
onMounted(load);
</script>
